import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const n="/llamatron/assets/clip.B5dT9_33.svg",r="/llamatron/assets/clip_strum.l1ffGnfS.svg",i="/llamatron/assets/chain_list.uSgPITAb.svg",b=JSON.parse('{"title":"Clips","description":"","frontmatter":{},"headers":[],"relativePath":"CLIPS.md","filePath":"CLIPS.md"}'),d={name:"CLIPS.md"};function h(c,e,l,p,g,m){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="clips" tabindex="-1">Clips <a class="header-anchor" href="#clips" aria-label="Permalink to &quot;Clips&quot;">​</a></h1><p>A clip is what a track plays in a scene: a pattern, and the settings that change how the pattern plays there. This page covers the clip page.</p><p><img src="'+n+'" alt="The Clip page"></p><h2 id="clips-on-arrange" tabindex="-1">Clips on Arrange <a class="header-anchor" href="#clips-on-arrange" aria-label="Permalink to &quot;Clips on Arrange&quot;">​</a></h2><p>A clip sits where a scene&#39;s row and a track&#39;s column meet on Arrange, so the clip page&#39;s crumb pairs the two, such as <code>ARRANGE › clip: (verse, bass)</code>. The crumbs always say where <code>ESC</code> goes back to. The pattern editor opened with <code>P</code> from a clip reads <code>ARRANGE › pattern: bass line</code> when opened from Arrange, <code>ARRANGE › clip: (verse, bass) › pattern: bass line</code> when opened from the clip page, and <code>PATTERNS › bass line</code> only when the Patterns page opened it.</p><h2 id="clip-settings" tabindex="-1">Clip Settings <a class="header-anchor" href="#clip-settings" aria-label="Permalink to &quot;Clip Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td>A name of the clip&#39;s own, shown on the grid and used for the clip in Live and in the clip tree&#39;s file names. Without one, the clip goes by its pattern&#39;s name. <code>Bksp</code> clears it.</td></tr><tr><td>Patterns</td><td>The patterns the clip plays, one after another, as one long pattern (see Pattern Lists below). A clip of 1 pattern is a list of 1. <code>A</code>, or <code>ENTER</code> on the <code>+</code> row, adds a pattern; <code>Bksp</code> takes the pattern under the cursor out of the list, which deletes no pattern; <code>M</code> picks the pattern up, the arrows carry it and <code>ENTER</code> drops it; <code>ENTER</code> or <code>J</code> opens the pattern in the pattern editor, and <code>ESC</code> comes back.</td></tr><tr><td>Scale</td><td>A scale of the clip&#39;s own, which wins over the scene&#39;s and the song&#39;s, so that one track can play in another key or mode. <code>ENTER</code> picks one, and <code>Bksp</code> goes back to the scene&#39;s, shown with where it comes from, such as <code>A Minor (from scene)</code>.</td></tr><tr><td>Chains</td><td>The chains of generators the clip runs, in order. <code>ENTER</code> opens the list, where <code>A</code> adds a chain, <code>M</code> moves one and <code>Bksp</code> takes one out; <code>Bksp</code> on the field clears them all. A clip runs its own chains first, then its scene&#39;s, then its track&#39;s. See <a href="./CHAINS">Chains</a>.</td></tr><tr><td>Pattern order</td><td>Which pattern of the list comes next, each pass through the list (see Pattern Lists below).</td></tr><tr><td>Step direction</td><td>Overrides the play direction of the steps inside each pattern of the list, and of the pattern the clip morphs to. <code>Bksp</code> goes back to each pattern&#39;s own direction, shown as <code>forward (from pattern)</code> or the like, or <code>(each pattern)</code> for a list of several.</td></tr><tr><td>Repeat</td><td>How many times the clip plays its whole list of patterns, from 1 to 9999, before staying silent while the scene&#39;s other clips finish.</td></tr><tr><td>Loop</td><td>Plays the clip until the scene&#39;s longest clip that doesn&#39;t loop is done. <code>Space</code> or <code>ENTER</code> toggles it.</td></tr><tr><td>Morph to</td><td>With Repeat above 1, a second pattern to change into across the repeats.</td></tr><tr><td>Morph direction</td><td><code>left</code>, <code>right</code> or <code>middle</code>: where the change sweeps in from.</td></tr><tr><td>Velocity</td><td>How loud the clip plays, as a percentage of each note&#39;s written velocity, over its scene&#39;s Velocity. Blank takes the scene&#39;s, shown as <code>80% (from scene)</code>, or 100%. See <a href="./SCENES#velocity-and-velocity-ramps">Velocity and Velocity Ramps</a>.</td></tr><tr><td>Grab track</td><td>Another track in the scene, whose notes the pattern&#39;s Grab steps play. <code>Bksp</code> sets none.</td></tr><tr><td>Advance</td><td>What the clip does in real-time playback when it finishes, as described under Advance below. <code>ENTER</code> chooses. A clip that sets none shows the set&#39;s default, such as <code>With Scene (from set)</code>.</td></tr><tr><td>+ Strum</td><td>A section, closed until opened, like the track editor&#39;s: Strum direction <code>(track)</code> takes the track&#39;s strum, shown as the direction it takes, such as <code>down (from track)</code>, <code>off</code> strums nothing whatever the track says, and any other direction strums this clip its own way. See <a href="./generators/STRUM">Strum</a>.</td></tr><tr><td>+ Velocity Ramp In, + Velocity Ramp Out</td><td>Sections, closed until opened, like the Scene page&#39;s, that fade this clip in and out. Each field set here wins over the scene&#39;s. See <a href="./SCENES#velocity-and-velocity-ramps">Velocity and Velocity Ramps</a>.</td></tr><tr><td>+ Density, + Articulate</td><td>Sections, closed until opened, like the Scene page&#39;s, shaping this clip across its own length. A shape set here wins over the scene&#39;s, and a generator in the clip&#39;s chains wins over both.</td></tr><tr><td>+ Set Registers, + Increment Registers</td><td>Sections, closed until opened, that set each register to a value as the clip starts and add an amount every time the clip&#39;s pattern starts over. See <a href="./REGISTERS#set-registers-and-increment-registers">Set Registers and Increment Registers</a>.</td></tr><tr><td>+ Bypass Generators When, + Skip Playback When</td><td>Sections of statements about the registers, read each time the clip&#39;s pattern starts over: the first lets a pass go by the clip&#39;s generators untouched, and the second makes the clip sit a pass out. See <a href="./REGISTERS#conditional-execution">Conditional Execution</a>.</td></tr><tr><td>Play, Stop</td><td>Buttons under the settings, which do what <code>L</code> (Listen) does: play the clip in real time as its scene would, with its chains, grabs, scale and direction, again and again until <code>L</code> is pressed again or Stop is. When the clip&#39;s track has no instrument, a list asks which of the set&#39;s instruments to listen through, for this listening alone. While the Real Time switch is off, the clip plays through General MIDI in <a href="./FLUIDSYNTH">FluidSynth</a> instead, the piano, or the drum kit for drums. See <a href="./PLAYING_LIVE">Playing Live</a>.</td></tr></tbody></table><h2 id="pattern-lists" tabindex="-1">Pattern Lists <a class="header-anchor" href="#pattern-lists" aria-label="Permalink to &quot;Pattern Lists&quot;">​</a></h2><p>A riff-based song is often a few bars said in different orders: the riff three times and then an answer, or three bars of a beat and a fill. A clip&#39;s list of patterns writes that down directly. The patterns play one after another as one long pattern, each at its own step size and in its own direction, and Repeat counts passes through the whole list. A pattern may be in a list more than once, and is named, never copied, so a change to the pattern is heard everywhere the pattern is listed. Drum patterns and patterns of notes never share a list. On Arrange, a clip of several patterns shows its first pattern and a count of the others, such as <code>riff-a +3</code>.</p><p>Pattern order chooses which pattern comes next. Every order plays every entry of the list once a pass, so a pass always lasts the same time. The names are the pattern directions, each meaning for whole patterns what the direction means for steps. For a list of <code>a</code>, <code>b</code>, <code>c</code>:</p><table tabindex="0"><thead><tr><th>Pattern order</th><th>First pass</th><th>Second pass</th></tr></thead><tbody><tr><td>forward</td><td>a b c</td><td>a b c</td></tr><tr><td>reverse a</td><td>a c b</td><td>a c b</td></tr><tr><td>reverse b</td><td>c b a</td><td>c b a</td></tr><tr><td>alternate</td><td>a b c</td><td>c b a</td></tr><tr><td>pendulum</td><td>a b c</td><td>b a c</td></tr><tr><td>random</td><td>drawn</td><td>drawn again</td></tr><tr><td>first, then random</td><td>a, then the others drawn</td><td>a, then drawn again</td></tr></tbody></table><p>A Restart When or Stop When statement on a step of any pattern in the list acts on the whole list: the list starts over, or the clip stops.</p><h2 id="morphing" tabindex="-1">Morphing <a class="header-anchor" href="#morphing" aria-label="Permalink to &quot;Morphing&quot;">​</a></h2><p>Morph to and Morph direction appear only when Repeat is above 1, and setting Repeat back to 1 removes the morph. The pattern being morphed to is looped or cut to the clip&#39;s length, and follows the clip&#39;s Direction when the clip has one; otherwise it follows its own pattern&#39;s direction, so a clip set to <code>eitherway</code> can finish its morph playing the second pattern backwards. A pattern with no notes morphs too, carrying its CC values and register changes across. The pattern being morphed to never grabs, and uses the registers without adding to them.</p><h2 id="grabbing-notes" tabindex="-1">Grabbing Notes <a class="header-anchor" href="#grabbing-notes" aria-label="Permalink to &quot;Grabbing Notes&quot;">​</a></h2><p>Grab track works like the Cirklon&#39;s note grab, and changes only the steps that the pattern&#39;s Grab row marks. Each marked step plays the note that the other track most recently started, at or before that step: the note the other track is playing, or the last note it played if it is silent. If the other track hasn&#39;t played anything yet, the step keeps its own note, or stays silent if the step has none.</p><p>When the other track plays a chord, the step takes the chord&#39;s root, the note the chord was built on, whatever its inversion or voice leading. A grab step with nothing on its Chord row plays that one note, and a grab step with a chord on its Chord row plays the chord with the grabbed note at the bottom: when the bass plays D and the step&#39;s chord is <code>m7</code>, the step plays D, F, A and C. The scale chords, <code>3</code> to <code>13</code>, add notes of the clip&#39;s scale above the grabbed note. A grab hears the other track after that track&#39;s chains run, so grabbing from an arpeggiated track takes the arpeggio&#39;s notes. Every other step, and everything else about the clip, such as its rhythm and velocity, stays the clip&#39;s own, and the grabbing track&#39;s transpose still applies.</p><p>Because grabbing is set on the clip, one pattern can grab from different tracks in different clips. A clip can grab from a track that grabs from another, but never in a circle: the clip page refuses a grab that would close a circle and says which clips to change, pasting a clip drops such a grab, and a set file with a circle stops exporting with a message naming the tracks.</p><h2 id="advance" tabindex="-1">Advance <a class="header-anchor" href="#advance" aria-label="Permalink to &quot;Advance&quot;">​</a></h2><p>Advance is Live&#39;s follow action: what a clip does in real-time playback when it finishes. No export reads it.</p><ul><li>&quot;With Scene&quot; starts the clip directly below when the whole scene is done.</li><li>&quot;Next&quot; starts the clip directly below as soon as this clip&#39;s own repeats end, whatever the rest of the scene is doing.</li><li>&quot;Off&quot; starts nothing, so the track falls silent until something launches it.</li></ul><p>A scene is done when every clip in it that doesn&#39;t loop has finished its repeats. A looping clip loops on until the scene below starts, so a scene whose every clip loops plays until you start something else. When the scene below has Launch together on, a start reaching any of its clips launches the whole scene and stops everything still playing in the scene above. A clip that sets nothing shows the File/Global page&#39;s Default follow action as its own.</p><h2 id="clip-strum-and-chains" tabindex="-1">Clip Strum and Chains <a class="header-anchor" href="#clip-strum-and-chains" aria-label="Permalink to &quot;Clip Strum and Chains&quot;">​</a></h2><p>A clip&#39;s sections set its own strum and shapes, over those of its track and its scene. In <code>examples/learning/13_classic_strum.yml</code>, this clip strums by the beat with a tight spread:</p><p><img src="'+r+'" alt="A clip&#39;s Strum section open"></p><p><code>ENTER</code> on a clip&#39;s Chains field opens the list of chains the clip runs, where <code>A</code> adds one:</p><p><img src="'+i+'" alt="A clip&#39;s chains"></p>',27)])])}const u=t(d,[["render",h]]);export{b as __pageData,u as default};
